def projected_delta246_record() -> dict[str, object]:
    """Independently replay the rank-six projected Delta(2,4,6) core."""

    scale = 15
    raw = [
        [-12, 6, 0],
        [6, -6, 3],
        [0, 3, -2],
    ]
    ambient = [
        [scale * raw[i][j] if j < 3 else raw[i][j - 3] for j in range(6)]
        for i in range(3)
    ] + [
        [raw[i][j] if j < 3 else (-2 if i == j - 3 else 0) for j in range(6)]
        for i in range(3)
    ]
    projector = [
        [
            Fraction(int(i == j))
            if j < 3
            else Fraction(int(i == j - 3), scale)
            for j in range(6)
        ]
        for i in range(3)
    ] + [[Fraction() for _ in range(6)] for _ in range(3)]
    ambient_fraction = [[Fraction(value) for value in row] for row in ambient]
    projector_ok = _matrix_product(projector, projector) == projector
    self_adjoint = _matrix_product(
        _transpose(projector), ambient_fraction
    ) == _matrix_product(ambient_fraction, projector)

    # The Schur complement is H-G/15.  Sylvester's criterion applied to
    # -(H-G/15), together with signature(G)=(1,2), gives signature(A)=(1,5).
    minus_schur = [
        [Fraction(2 if i == j else 0) + Fraction(raw[i][j], scale) for j in range(3)]
        for i in range(3)
    ]
    schur_minors = [
        _determinant([row[:size] for row in minus_schur[:size]])
        for size in range(1, 4)
    ]

    ellipsoid = [
        [30 + raw[i][i] if i == j else raw[i][j] for j in range(3)]
        for i in range(3)
    ]
    ellipsoid_survivors = [
        vector
        for a0 in range(-1, 2)
        for a1 in range(-1, 2)
        for a2 in range(-1, 2)
        if _quadratic(ellipsoid, vector := (a0, a1, a2)) < 30
    ]
    expected_survivors = [
        (-1, 0, 0),
        (0, -1, 0),
        (0, 0, -1),
        (0, 0, 0),
        (0, 0, 1),
        (0, 1, 0),
        (1, 0, 0),
    ]

    return {
        "raw_field": "Q",
        "scale": scale,
        "ambient_Picard_rank": 6,
        "projected_eigenslice_rank": 3,
        "ambient_determinant": int(_determinant(ambient)),
        "ambient_signature": [1, 5]
        if all(value > 0 for value in schur_minors)
        else None,
        "projector_idempotent": projector_ok,
        "projector_self_adjoint": self_adjoint,
        "finite_ellipsoid_survivors": ellipsoid_survivors,
        "ellipsoid_reduces_to_zero_and_signed_basis": (
            ellipsoid_survivors == expected_survivors
        ),
        "P1_full_raw_module_primitive_in_NS": True,
        "old_literal_rational_P2": False,
        "revised_exact_projected_eigen_nef_P2": True,
        "P3_minimal_K3_K_numerically_zero": True,
        "P4_this_input": True,
        "P4_universal_projected_category": False,
        "raw_reflections_integral_on_NS": False,
        "raw_reflections_rational_on_NS_Q": True,
        "ambient_root_reflections_are_raw_reflections": False,
        "finite_projected_host_control": False,
        "K3_projected_category_n_max": 19,
        "nonrational_members_require_full_trace_admissibility": True,
    }


