def corrected_genus_one_record(n: int) -> dict[str, object]:
    if n < 12:
        raise ValueError("the corrected packet starts at P12")
    canonical = (-3,) + (1,) * n
    curve = (3,) + (-1,) * 11 + (0,) * (n - 11)
    tail = tuple(a + b for a, b in zip(curve, canonical))
    quartic_count = min(n, 18)
    quartic = (4,) + (-1,) * quartic_count + (0,) * (n - quartic_count)
    return {
        "dimension": n,
        "C_square": dot(curve, curve),
        "K_dot_C": dot(canonical, curve),
        "C_genus": 1 + (dot(curve, curve) + dot(canonical, curve)) // 2,
        "C_dot_Z": dot(curve, tail),
        "Z_square": dot(tail, tail),
        "quartic_exceptional_count": quartic_count,
        "A_square": dot(quartic, quartic),
        "K_dot_A": dot(canonical, quartic),
        "A_genus": 1 + (dot(quartic, quartic) + dot(canonical, quartic)) // 2,
        "C_dot_A": dot(curve, quartic),
        "full_nef_carrier": n <= 16,
    }


